package com.zzy.ksongfloat.ai;
import com.zzy.ksongfloat.ai.model.*; import org.json.*; import java.util.*;
public class AiResponseParser { public AiAnalysisResult parse(String content) throws Exception { if(content==null||content.trim().isEmpty()) throw new Exception("AI 返回内容为空"); String json=extractJson(stripFence(content.trim())); JSONObject o=new JSONObject(json); AiAnalysisResult r=new AiAnalysisResult(); r.pageType=safeType(o.optString("pageType","UNKNOWN")); r.nickname=lim(o.optString("nickname",""),50); r.profileSummary=lim(o.optString("profileSummary",""),120); r.musicPreferences=strList(o.optJSONArray("musicPreferences"),5,60); r.conversationAngles=strList(o.optJSONArray("conversationAngles"),5,80); r.commentSuggestions=sugList(o.optJSONArray("commentSuggestions"),3,100); r.privateMessageSuggestions=sugList(o.optJSONArray("privateMessageSuggestions"),3,150); r.riskFlags=riskList(o.optJSONArray("riskFlags"),10); r.confidence=Math.max(0,Math.min(1,o.optDouble("confidence",0))); new AiResponseValidator().validate(r); return r; }
 public String stripFence(String s){ if(s.startsWith("```")){ int first=s.indexOf('\n'); int last=s.lastIndexOf("```"); if(first>=0&&last>first)return s.substring(first+1,last).trim(); } return s; }
 public String extractJson(String s)throws Exception{ int start=s.indexOf('{'); int end=s.lastIndexOf('}'); if(start<0||end<=start) throw new Exception("未找到 JSON 对象"); return s.substring(start,end+1); }
 private String safeType(String t){ try{ com.zzy.ksongfloat.classifier.PageType.valueOf(t); return t;}catch(Exception e){return "UNKNOWN";} } private String lim(String s,int n){return s==null?"":(s.length()>n?s.substring(0,n):s);} private List<String> strList(JSONArray a,int max,int len){ List<String> out=new ArrayList<>(); if(a!=null) for(int i=0;i<a.length()&&out.size()<max;i++){String v=lim(a.optString(i,""),len); if(!v.trim().isEmpty())out.add(v);} return out;} private List<SuggestionItem> sugList(JSONArray a,int max,int len){ List<SuggestionItem> out=new ArrayList<>(); if(a!=null) for(int i=0;i<a.length()&&out.size()<max;i++){JSONObject o=a.optJSONObject(i); if(o==null)continue; String text=lim(o.optString("text",""),len); if(!text.trim().isEmpty())out.add(new SuggestionItem(text,lim(o.optString("reason",""),100)));} return out;} private List<AiRiskFlag> riskList(JSONArray a,int max){ List<AiRiskFlag> out=new ArrayList<>(); if(a!=null) for(int i=0;i<a.length()&&out.size()<max;i++){JSONObject o=a.optJSONObject(i); if(o!=null)out.add(new AiRiskFlag(lim(o.optString("code",""),40),lim(o.optString("message",""),120)));} return out;} }
